export type GumMode = 'NotFoundError' | 'NotAllowedError';

/** Подмена getUserMedia до загрузки страницы: отказ с нужным DOMException (как «нет микрофона» / «доступ запрещён»). */
export const failGetUserMedia = (mode: string) => {
  const md = navigator.mediaDevices;
  if (!md) return;
  const fake = () => Promise.reject(new DOMException('qa mock', mode));
  try {
    Object.defineProperty(md, 'getUserMedia', { value: fake, configurable: true, writable: true });
  } catch {
    (md as unknown as { getUserMedia: unknown }).getUserMedia = fake;
  }
};

/** Открыть ссылку и дождаться экрана «ברוכים הבאים». */
export async function openWelcome(page: Page, link: string) {
  await page.goto(link);
  await expect(page.getByRole('button', { name: A11Y.welcomeCta })).toBeVisible({ timeout: 30_000 });
}

/** Новый кандидат: ברוכים הבאים → איך זה עובד → פרטי הלקוח → лист «לפני שמתחילים» (галочка не отмечена). */
export async function toConsent(page: Page, link: string) {
  await openWelcome(page, link);
  await tapBtn(page, A11Y.welcomeCta);
  await tapBtn(page, A11Y.howCta);
  await tapBtn(page, A11Y.clientCta);
  await expect(page.getByText(A11Y.consentTitle).first()).toBeVisible();
}

/** Новый кандидат: … → согласие → вступление тех. проверки («להתחיל בדיקה»). */
export async function toTechCheckIntro(page: Page, link: string) {
  await toConsent(page, link);
  await page.getByRole('checkbox').first().check();
  await tapBtn(page, A11Y.consentCta);
  await expect(page.getByRole('button', { name: TECH.start })).toBeVisible({ timeout: 30_000 });
}

/** Кнопка «?» в шапке (скрытое имя «…פנייה לגורם אנושי»). */
export const helpEntry = (page: Page) => page.getByTestId('help-entry').filter({ visible: true }).first();

/** Самый внутренний блок, где есть и заголовок «צריכים עזרה?», и поле описания, — сам лист помощи. */
export const helpSheet = (page: Page): Locator =>
  page
    .locator('div')
    .filter({ has: page.getByText(HELP.title, { exact: true }) })
    .filter({ has: page.getByRole('textbox', { name: HELP.description }) })
    .last();

export async function openHelp(page: Page, open?: () => Promise<void>) {
  if (open) await open();
  else await helpEntry(page).click();
  await expect(page.getByText(HELP.title, { exact: true }).filter({ visible: true }).first()).toBeVisible();
  await expect(page.getByRole('textbox', { name: HELP.description })).toBeVisible();
}

export async function closeHelp(page: Page) {
  await tapBtn(page, HELP.close);
  await expect(page.getByText(HELP.title, { exact: true }).filter({ visible: true })).toHaveCount(0);
}

export type Box = { x: number; y: number; w: number; h: number };
export type SheetMetrics = {
  chips: { name: string; h: number; top: number }[];
  tel: (Box & { pt: number; pb: number; text: string }) | null;
  mail: (Box & { pt: number; pb: number; text: string }) | null;
  nested: boolean;
  textarea: { h: number; resize: string } | null;
};

/** Замеры листа помощи: чипы типов (высота/верх), ссылки tel:/mailto: (рамка, отступы), поле описания. */
export async function sheetMetrics(sheet: Locator, chips: string[] = HELP.chips): Promise<SheetMetrics> {
  return sheet.evaluate((root, names) => {
    const box = (e: Element) => {
      const r = e.getBoundingClientRect();
      return { x: r.left, y: r.top, w: r.width, h: r.height };
    };
    const visible = (e: Element) => (e as HTMLElement).getClientRects().length > 0 && getComputedStyle(e).visibility !== 'hidden';
    // Чип = видимая «таблетка»: label вокруг input[type=radio], либо сам [role=radio].
    const radios = Array.from(root.querySelectorAll('input[type=radio], [role=radio]'));
    const out: { name: string; h: number; top: number }[] = [];
    for (const n of names) {
      const r = radios.find((x) => {
        const holder = (x.closest('label') || x) as HTMLElement;
        return (holder.innerText || x.getAttribute('aria-label') || '').trim().includes(n);
      });
      if (!r) continue;
      let chip = (r.closest('label') || r) as HTMLElement;
      if (!visible(chip) || chip.getBoundingClientRect().height < 2) chip = (r.parentElement || chip) as HTMLElement;
      const b = box(chip);
      out.push({ name: n, h: Math.round(b.h * 10) / 10, top: Math.round(b.y) });
    }
    const link = (sel: string) => {
      const a = Array.from(root.querySelectorAll(sel)).filter(visible).pop() as HTMLElement | undefined;
      if (!a) return null;
      const cs = getComputedStyle(a);
      return { ...box(a), pt: parseFloat(cs.paddingTop), pb: parseFloat(cs.paddingBottom), text: a.innerText.trim() };
    };
    const telEl = Array.from(root.querySelectorAll('a[href^="tel:"]')).filter(visible).pop();
    const mailEl = Array.from(root.querySelectorAll('a[href^="mailto:"]')).filter(visible).pop();
    const nested = !!(telEl && mailEl && (telEl.contains(mailEl) || mailEl.contains(telEl)));
    const ta = root.querySelector('textarea');
    return {
      chips: out,
      tel: link('a[href^="tel:"]'),
      mail: link('a[href^="mailto:"]'),
      nested,
      textarea: ta ? { h: Math.round(ta.getBoundingClientRect().height * 10) / 10, resize: getComputedStyle(ta).resize } : null,
    };
  }, chips);
}

/** Промежуток между двумя прямоугольниками: по горизонтали, если они в одном ряду, иначе по вертикали. */
export function gapBetween(a: Box, b: Box): number {
  const sameRow = a.y < b.y + b.h && b.y < a.y + a.h;
  if (sameRow) return Math.max(b.x - (a.x + a.w), a.x - (b.x + b.w));
  return Math.max(b.y - (a.y + a.h), a.y - (b.y + b.h));
}

export async function noHorizontalScroll(page: Page, label: string) {
  const { sw, vw } = await page.evaluate(() => ({ sw: document.documentElement.scrollWidth, vw: window.innerWidth }));
  expect(sw, `горизонтальная прокрутка (${label}): scrollWidth ${sw} > ${vw}`).toBeLessThanOrEqual(vw);
}
